public sealed class MotionContour40:IDisposable {
 readonly NativePlayer395 native;readonly string root;InputSettings settings;string settingsJSON;Keyboard priorKeyboard,ownedKeyboard;InputSettings.BackgroundBehavior oldBackground;InputSettings.EditorInputBehaviorInPlayMode oldEditor;float oldCapture;PlayerMovement movement;Animator animator;bool started,disposed,turned;int direction;readonly Dictionary<GameInputActionId,Key> bound=new Dictionary<GameInputActionId,Key>();public int FirstTarget{get;private set;}public bool Restored{get;private set;}public Obj40 RestoreReport{get;private set;}public Arr40 events=new Arr40();
