  settings=InputSystem.settings;if(!settings||EditorUtility.IsPersistent(settings))throw new InvalidOperationException("40 expected live nonpersistent input settings; no replacement");settingsJSON=JsonUtility.ToJson(settings);oldBackground=settings.backgroundBehavior;oldEditor=settings.editorInputBehaviorInPlayMode;priorKeyboard=Keyboard.current;oldCapture=Time.captureDeltaTime;
  CreateOnly40.Text(Path.Combine(root,"MOTION_INPUT_BEFORE40.json"),new Obj40{["inputId"]=settings.GetEntityId().ToString(),["json"]=settingsJSON,["background"]=oldBackground.ToString(),["editor"]=oldEditor.ToString(),["captureDelta"]=oldCapture,["priorKeyboard"]=priorKeyboard!=null?priorKeyboard.deviceId:-1,["devices"]=new Arr40(InputSystem.devices.Select(d=>new Obj40{["id"]=d.deviceId,["enabled"]=d.enabled})),["settingsReplacement"]=false,["movementSpeedModified"]=false,["animatorSpeedModified"]=false}.ToString());started=true;
  float best=-2;for(int i=0;i<8;i++){float a=Vector3.Dot(animator.transform.forward,PlayerMovement.CalculateCameraRelativeDirection(D[i],camera.transform.rotation));if(a>best){best=a;direction=i;}}
  settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;settings.editorInputBehaviorInPlayMode=InputSettings.EditorInputBehaviorInPlayMode.AllDeviceInputAlwaysGoesToGameView;ownedKeyboard=InputSystem.AddDevice<Keyboard>("Contour40 isolated normal gameplay input");ownedKeyboard.MakeCurrent();
