 public Obj40 Snapshot(){int index=Time.frameCount-FirstTarget;var expected=D[((index<3?direction:direction+2)+8)%8];var actual=GameInputBindings.ReadMovement();bool match=actual.sqrMagnitude>0&&Vector2.Dot(actual.normalized,expected.normalized)>.999f;return new Obj40{["frame"]=Time.frameCount,["index"]=index,["stage"]=index<3?"walk":"turn",["expected"]=V(expected),["actualInput"]=V(actual),["matches"]=match,["playerPosition"]=V(native.player.position),["avatarRotation"]=Q(animator.transform.rotation),["avatarPosition"]=V(animator.transform.position),["movementSpeed"]=movement.CurrentMoveSpeed,["deltaTime"]=Time.deltaTime,["captureDeltaTime"]=Time.captureDeltaTime,["timeScale"]=Time.timeScale,["inputReference"]=InputSystem.settings.GetEntityId().ToString()};}
